SELECT
  b.BUILDING_NAME AS building_name,
  COUNT(DISTINCT d.ACTIVITY_TITLE) AS total_subjects,
  SUM(COALESCE(d.FEE, 0)) AS total_fee,
  SEC_TO_TIME(
    MIN(
      TIME_TO_SEC(
        STR_TO_DATE(
          CONCAT(
            LPAD(SUBSTRING(s.SESSION_END_TIME, 1, LENGTH(s.SESSION_END_TIME) - 2), 4, '0'),
            SUBSTRING(s.SESSION_END_TIME, -2)
          ),
          '%h%i%p'
        )
      ) - TIME_TO_SEC(
        STR_TO_DATE(
          CONCAT(
            LPAD(SUBSTRING(s.SESSION_START_TIME, 1, LENGTH(s.SESSION_START_TIME) - 2), 4, '0'),
            SUBSTRING(s.SESSION_START_TIME, -2)
          ),
          '%h%i%p'
        )
      )
    )
  ) AS shortest_session,
  SEC_TO_TIME(
    MAX(
      TIME_TO_SEC(
        STR_TO_DATE(
          CONCAT(
            LPAD(SUBSTRING(s.SESSION_END_TIME, 1, LENGTH(s.SESSION_END_TIME) - 2), 4, '0'),
            SUBSTRING(s.SESSION_END_TIME, -2)
          ),
          '%h%i%p'
        )
      ) - TIME_TO_SEC(
        STR_TO_DATE(
          CONCAT(
            LPAD(SUBSTRING(s.SESSION_START_TIME, 1, LENGTH(s.SESSION_START_TIME) - 2), 4, '0'),
            SUBSTRING(s.SESSION_START_TIME, -2)
          ),
          '%h%i%p'
        )
      )
    )
  ) AS longest_session
FROM IAP_SUBJECT_SESSION s
JOIN IAP_SUBJECT_DETAIL d
  ON d.IAP_SUBJECT_SESSION_KEY = s.IAP_SUBJECT_SESSION_KEY
JOIN BUILDINGS b
  ON b.BUILDING_NUMBER = s.SESSION_LOCATION
WHERE s.SESSION_LOCATION IS NOT NULL
  AND TRIM(s.SESSION_LOCATION) <> ''
GROUP BY
  b.BUILDING_NAME;
